"<?=cc_h($s['settings']['current']['take_profit_percent']??5)?>"></label><button class="btn secondary">اجرای سناریو</button></form><?php if(is_array($lab)):?><div class="metric-grid"><div class="metric"><span>Samples</span><b><?=$lab['samples']?></b></div><div class="metric"><span>Win Rate</span><b><?=cc_n($lab['win_rate_percent'],1)?>%</b></div><div class="metric"><span>Avg</span><b><?=cc_n($lab['average_simulated_return_percent'],3)?>%</b></div><div class="metric"><span>Max DD</span><b><?=cc_n($lab['max_drawdown_percent'],2)?>%</b></div></div><small><?=cc_h($lab['note'])?></small><?php endif?></section></div>

